import { Container, Rectangle, Texture } from 'pixi.js';
import { GCSymbolView, GRSymbolView, } from '../slots';

export interface ISize {
    width: number;
    height: number;
}
export interface ISpinningData {
    isModelSpinning: boolean;
    isReelSpinning: boolean;
}

export interface ICoreSettings {
    topOffset: number;
    bottomOffset: number;
    viewMaskYOffset: number;
    viewMaskTexture?: Texture;
    allowZIndexSymbolSorting: boolean;
    recursiveTransforming: boolean;
    snapshotInjection: boolean;
}

export interface ISymbolSettings {
    frameTransfrom: Rectangle;
}

export enum BlendLevel {
    none = 0,
    jump = 1,
    onlySlow = 2,
    full = 3,
}

export enum SpinState {
    STOPPED = 0,
    WAITING_TO_STOP = 1,
    SPINNING = 2
}
export interface IBounceSettings {
    elasticStopIntensity: number;
    elasticStopDuration: number;
    elasticBounceAmplitude: number;
    elasticBouncePeriod: number;
}

export interface IAccelerationSettings {
    limit: number;
    steps: number[];
}

export interface ISpeedSettings {
    acceleration: IAccelerationSettings;
    deceleration: IAccelerationSettings;
}

export interface IReelSettings {
    bounceSettings: IBounceSettings;
    rollbackSpeed: number;
    reelStartDelay: number;
    symbolVerticalPadding: number;
    stoppingBlendMode: BlendLevel;
    speedSettings: ISpeedSettings;
}

export interface IReelEvents {
    ON_BEGIN_SPIN_BEFORE_TICK: () => void,
    ON_REEL_SPINNING_BEFORE_TICK: () => void,
    ON_REEL_SPINNING_AFTER_TICK: () => void,
    ON_REEL_STOP: () => void,
    ON_SYMBOL_POSITION_SET_BEFORE_TICK: (symbol: Container) => void,
    ON_SYMBOL_POSITION_SET_AFTER_TICK: (symbol: Container) => void,
}

export interface IReelEffects {
    REEL_STOP_EFFECT: (reelStopData: IReelStopData) => void,
}

export type GRReelEvent = {
    reelEvent: IReelEvents;
    reelEffect: IReelEffects;
}

// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface ISymbolEvents {
}

export type GRSymbolEvent = {
    symbolEvent: ISymbolEvents
}

export interface IServiceEvents {
    ON_SPIN_STATE_CHANGED: (states: number[]) => void,
    ON_SCREENREELS_CHANGED: (reels: number[][]) => void,
    ON_SPIN_SPEED_CHANGED: (spinSpeedValues: number[]) => void,
    ON_SPIN_COMPLETE: () => void,
    ON_SEQUENCE_STEP: () => void,
}
export type GRServiceEvent = {
    serviceEvent: IServiceEvents
}

export interface IGenericReelCommands {
    stepSpinSequence: () => void,
    registerReel: (reelIndex: number) => RegisterResponse
}

export interface RegisterResponse {
    success: boolean;
}

export type GRSymbolType = GRSymbolView | GCSymbolView;
export interface IReelStopData {
    symbol: GRSymbolType,
    inertia: number,
    endPosition: number
}

export interface IReelValidation {
    validated: boolean,
    unvalidatedStepCount: number,
    validate: () => void,
    invalidate: () => void,
    run: () => void,
}

export interface IMapIndex {
    value: number;
    increase: () => void;
    decrease: () => void;
}

export interface IDisplayReelData {
    displayReels: number[][];
    includesOffset: boolean;
}
export interface ISymbolData {
    index: number;
    skin: number;
    onScreen: boolean;
}

export interface IParentReelData {
    index: number;
    speed: number;
    spinning: boolean;
}
export interface ISpeedControl {
    speed: number;
    speedLimit: number;
    increment: number;
    decrement: number;
    incrementStep: number;
    decrementStep: number;
    accelerationLimit: number;
    decelerationLimit: number;
    speedLimitDecreased: boolean;
    reset: () => void;
    calculateSpeed: (delta: number) => void;
    calculateIncrement: () => void;
    calculateDecrement: () => void;
}
export interface IReelSpeedConfig {
    speed: number;
    overrides?: Record<number, number>;
}